iv><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="二、客户端采集优势与限制" tabindex="-1"><a class="header-anchor" href="#二、客户端采集优势与限制"><span>二、客户端采集优势与限制</span></a></h3>
<h4 id="_2-1-适合客户端采集的指标" tabindex="-1"><a class="header-anchor" href="#_2-1-适合客户端采集的指标"><span>2.1 适合客户端采集的指标</span></a></h4>
<table>
<thead>
<tr>
<th>指标类别</th>
<th>具体指标</th>
<th>采集优势</th>
<th>实现方式</th>
</tr>
</thead>
<tbody>
<tr>
<td><strong>UI/UX体验</strong></td>
<td>按钮点击、页面停留时长</td>
<td>精确的交互时序</td>
<td>UI事件监听</td>
</tr>
<tr>
<td><strong>性能监控</strong></td>
<td>FPS、内存使用、加载时间</td>
<td>客户端独有数据</td>
<td>系统API调用</td>
</tr>
<tr>
<td><strong>设备环境</strong></td>
<td>设备型号、OS版本、网络状态</td>
<td>硬件信息获取</td>
<td>平台API</td>
</tr>
<tr>
<td><strong>操作行为</strong></td>
<td>手势轨迹、操作序列</td>
<td>完整操作链条</td>
<td>输入系统监听</td>
</tr>
<tr>
<td><strong>崩溃异常</strong></td>
<td>崩溃堆栈、ANR</td>
<td>异常现场信息</td>
<td>异常处理器</td>
</tr>
</tbody>
</table>
<h4 id="_2-2-客户端采集挑战与解决方案" tabindex="-1"><a class="header-anchor" href="#_2-2-客户端采集挑战与解决方案"><span>2.2 客户端采集挑战与解决方案</span></a></h4>
<table>
<thead>
<tr>
<th>挑战</th>
<th>问题描述</th>
<th>解决方案</th>
<th>实施要点</th>
</tr>
</thead>
<tbody>
<tr>
<td><strong>防作弊</strong></td>
<td>客户端数据可能被篡改</td>
<td>数字签名+服务器验证</td>
<td>关键数据双重验证</td>
</tr>
<tr>
<td><strong>网络依赖</strong></td>
<td>离线状态下数据丢失</td>
<td>本地存储+断线重连</td>
<td>队列持久化</td>
</tr>
<tr>
<td><strong>性能影响</strong></td>
<td>频繁采集影响游戏性能</td>
<td>智能采样+批量上传</td>
<td>采样率动态调整</td>
</tr>
<tr>
<td><strong>隐私合规</strong></td>
<td>用户隐私保护</td>
<td>数据脱敏+用户授权</td>
<td>合规性检查</td>
</tr>
</tbody>
</table>
<div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre v-pre><code class="language-csharp"><span class="line"><span class="token comment">// 防作弊签名实现</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">SecurityUtils</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> <span class="token function">SignEvent</span><span class="token punctuation">(</span><span class="token class-name">AnalyticsEvent</span> eventData<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> secretKey<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">var</span></span> payload <span class="token operator">=</span> <span class="token interpolation-string"><span class="token string">$"</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">eventData<span class="token punctuation">.</span>UserID</span><span class="token punctuation">}</span></span><span class="token string">|</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">eventData<span class="token punctuation">.</span>EventName</span><span class="token punctuation">}</span></span><span class="token string">|</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">eventData<span class="token punctuation">.</span>Timestamp</span><span class="token punctuation">}</span></span><span class="token string">|</span><span class="token interpolation"><span class="token punctuation">{</span><span class="token expression language-csharp">JsonConvert<span class="token punctuation">.</span><span class="token function">SerializeObject</span><span class="token punctuation">(</span>eventData<span class="token punctuation">.</span>Properties<span class="token punctuation">)</span></span><span class="token punctuation">}</span></span><span class="token string">"</span></span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token function">ComputeHMACSHA256</span><span class="token punctuation">(</span>payload<span class="token punctuation">,</span> secretKey<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">private</span> <span class="token keyword">static</span> <span class="token return-type class-name"><span class="token keyword">string</span></span> <span class="token function">ComputeHMACSHA256</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> message<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> secret<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">var</span></span> keyBytes <span class="token operator">=</span> Encoding<span class="token punctuation">.</span>UTF8<span class="token punctuation">.</span><span class="token function">GetBytes</span><span class="token punctuation">(</span>secret<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token class-name"><span class="token keyword">var</span></span> messageBytes <span class="token operator">=</span> Encoding<span class="token punctuation">.</span>UTF8<span class="token punctuation">.</span><span class="token function">GetBytes</span><span class="token punctuation">(</span>message<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">using</span> <span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">var</span></span> hmac <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">System<span class="token punctuation">.</span>Security<span class="token punctuation">.</span>Cryptography<span class="token punctuation">.</span>HMACSHA256</span><span class="token punctuation">(</span>keyBytes<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            <span class="token class-name"><span class="token keyword">var</span></span> hashBytes <span class="token operator">=</span> hmac<span class="token punctuation">.</span><span class="token function">ComputeHash</span><span class="token punctuation">(</span>messageBytes<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">return</span> Convert<span class="token punctuation">.</span><span class="token function">ToBase64String</span><span class="token punctuation">(</span>hashBytes<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🖥️-服务器端采集策略" tabindex="-1"><a class="header-anchor" href="#🖥️-服务器端采集策略"><span>🖥️ 服务器端采集策略</span></a></h2>
<h3 id="一、服务器端数据源" tabindex="-1"><a class="header-anchor" href="#一、服务器端数据源"><span>一、服务器端数据源</span></a></h3>
<h4 id="_1-1-游戏逻辑服务器" tabindex="-1"><a class="header-anchor" href="#_1-1-游戏逻辑服务器"><span>1.1 游戏逻辑服务器</span></a></h4>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token keyword">package</span> analytics</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">"context"</span></span>
<span class="line">    <span class="token string">"encoding/json"</span></span>
<span class="line">    <span class="token string">"log"</span></span>
<span class="line">    <span class="token string">"time"</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">"go.opentelemetry.io/otel"</span></span>
<span class="line">    <span class="token string">"go.opentelemetry.io/otel/attribute"</span></span>
<span class="line">    <span class="token string">"go.opentelemetry.io/otel/metric"</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> GameEventCollector <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    tracer otel<span class="token punctuation">.</span>Tracer</span>
<span class="line">    meter  otel<span class="token punctuation">.</span>Meter</span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 核心指标</span></span>
<span class="line">    userLoginCounter     metric<span class="token punctuation">.</span>Int64Counter</span>
<span class="line">    levelCompleteCounter metric<span class="token punctuation">.</span>Int64Counter</span>
<span class="line">    currencyEarnCounter  metric<span class="token punctuation">.</span>Int64Counter</span>
<span class="line">    currencySpendCounter metric<span class="token punctuation">.</span>Int64Counter</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewGameEventCollector</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>GameEventCollector <span class="token punctuation">{</span></span>
<span class="line">    tracer <span class="token operator">:=</span> otel<span class="token punctuation">.</span><span class="token function">Tracer</span><span class="token punctuation">(</span><span class="token string">"game.server"</span><span class="token punctuation">)</span></span>
<span class="line">    meter <span class="token operator">:=</span> otel<span class="token punctuation">.</span><span class="token function">Meter</span><span class="token punctuation">(</span><span class="token string">"game.server"</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token operator">&amp;</span>GameEventCollector<span class="token punctuation">{</span></span>
<span class="line">        tracer<span class="token punctuation">:</span> tracer<span class="token punctuation">,</span></span>
<span class="line">        meter<span class="token punctuation">:</span>  meter<span class="token punctuation">,</span></span>
<span class="line">        userLoginCounter<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.user.login.total"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        levelCompleteCounter<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.level.complete.total"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        currencyEarnCounter<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.currency.earn.total"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        currencySpendCounter<span class="token punctuation">:</span> meter<span class="token punctuation">.</span><span class="token function">Int64Counter</span><span class="token punctuation">(</span><span class="token string">"game.currency.spend.total"</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 用户登录事件</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>g <span class="token operator">*</span>GameEventCollector<span class="token punctuation">)</span> <span class="token function">TrackUserLogin</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> req UserLoginRequest<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    ctx<span class="token punctuation">,</span> span <span class="token operator">:=</span> g<span class="token punctuation">.</span>tracer<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">"user.login"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">defer</span> span<span class="token punctuation">.</span><span class="token function">End</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    span<span class="token punctuation">.</span><span class="token function">SetAttributes</span><span class="token punctuation">(</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"user.id"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>UserID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"login.method"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>Method<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"client.ip"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>ClientIP<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"device.platform"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>Platform<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    g<span class="token punctuation">.</span>userLoginCounter<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> metric<span class="token punctuation">.</span><span class="token function">WithAttributes</span><span class="token punctuation">(</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"game.id"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>GameID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"game.env"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>Environment<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"login.method"</span><span class="token punctuation">,</span> req<span class="token punctuation">.</span>Method<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 发送到消息队列</span></span>
<span class="line">    event <span class="token operator">:=</span> GameEvent<span class="token punctuation">{</span></span>
<span class="line">        EventType<span class="token punctuation">:</span> <span class="token string">"user.login"</span><span class="token punctuation">,</span></span>
<span class="line">        UserID<span class="token punctuation">:</span>    req<span class="token punctuation">.</span>UserID<span class="token punctuation">,</span></span>
<span class="line">        GameID<span class="token punctuation">:</span>    req<span class="token punctuation">.</span>GameID<span class="token punctuation">,</span></span>
<span class="line">        Timestamp<span class="token punctuation">:</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Properties<span class="token punctuation">:</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">{</span></span>
<span class="line">            <span class="token string">"login_method"</span><span class="token punctuation">:</span> req<span class="token punctuation">.</span>Method<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"client_ip"</span><span class="token punctuation">:</span>   req<span class="token punctuation">.</span>ClientIP<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"platform"</span><span class="token punctuation">:</span>    req<span class="token punctuation">.</span>Platform<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"server_time"</span><span class="token punctuation">:</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Unix</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    g<span class="token punctuation">.</span><span class="token function">publishEvent</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> event<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
