<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token keyword">type</span> PaymentEventCollector <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    tracer otel<span class="token punctuation">.</span>Tracer</span>
<span class="line">    meter  otel<span class="token punctuation">.</span>Meter</span>
<span class="line"></span>
<span class="line">    revenueCounter     metric<span class="token punctuation">.</span>Float64Counter</span>
<span class="line">    transactionCounter metric<span class="token punctuation">.</span>Int64Counter</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>p <span class="token operator">*</span>PaymentEventCollector<span class="token punctuation">)</span> <span class="token function">TrackPayment</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> payment PaymentEvent<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    ctx<span class="token punctuation">,</span> span <span class="token operator">:=</span> p<span class="token punctuation">.</span>tracer<span class="token punctuation">.</span><span class="token function">Start</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">"economy.payment"</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">defer</span> span<span class="token punctuation">.</span><span class="token function">End</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    span<span class="token punctuation">.</span><span class="token function">SetAttributes</span><span class="token punctuation">(</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"user.id"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>UserID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"order.id"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>OrderID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"product.id"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>ProductID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">Float64</span><span class="token punctuation">(</span><span class="token string">"amount"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Amount<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"currency"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Currency<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"status"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Status<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"payment.method"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>PaymentMethod<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 只有成功支付才计入收入</span></span>
<span class="line">    <span class="token keyword">if</span> payment<span class="token punctuation">.</span>Status <span class="token operator">==</span> <span class="token string">"success"</span> <span class="token punctuation">{</span></span>
<span class="line">        p<span class="token punctuation">.</span>revenueCounter<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Amount<span class="token punctuation">,</span> metric<span class="token punctuation">.</span><span class="token function">WithAttributes</span><span class="token punctuation">(</span></span>
<span class="line">            attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"product.id"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>ProductID<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"currency"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Currency<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"payment.method"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>PaymentMethod<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    p<span class="token punctuation">.</span>transactionCounter<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> metric<span class="token punctuation">.</span><span class="token function">WithAttributes</span><span class="token punctuation">(</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"status"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>Status<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        attribute<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token string">"payment.method"</span><span class="token punctuation">,</span> payment<span class="token punctuation">.</span>PaymentMethod<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    event <span class="token operator">:=</span> GameEvent<span class="token punctuation">{</span></span>
<span class="line">        EventType<span class="token punctuation">:</span> <span class="token string">"economy.payment"</span><span class="token punctuation">,</span></span>
<span class="line">        UserID<span class="token punctuation">:</span>    payment<span class="token punctuation">.</span>UserID<span class="token punctuation">,</span></span>
<span class="line">        GameID<span class="token punctuation">:</span>    payment<span class="token punctuation">.</span>GameID<span class="token punctuation">,</span></span>
<span class="line">        Timestamp<span class="token punctuation">:</span> time<span class="token punctuation">.</span><span class="token function">Now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        Properties<span class="token punctuation">:</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token keyword">interface</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">{</span></span>
<span class="line">            <span class="token string">"order_id"</span><span class="token punctuation">:</span>       payment<span class="token punctuation">.</span>OrderID<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"product_id"</span><span class="token punctuation">:</span>     payment<span class="token punctuation">.</span>ProductID<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"amount"</span><span class="token punctuation">:</span>         payment<span class="token punctuation">.</span>Amount<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"currency"</span><span class="token punctuation">:</span>       payment<span class="token punctuation">.</span>Currency<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"status"</span><span class="token punctuation">:</span>         payment<span class="token punctuation">.</span>Status<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"payment_method"</span><span class="token punctuation">:</span> payment<span class="token punctuation">.</span>PaymentMethod<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"platform_fee"</span><span class="token punctuation">:</span>   payment<span class="token punctuation">.</span>PlatformFee<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"net_revenue"</span><span class="token punctuation">:</span>    payment<span class="token punctuation">.</span>Amount <span class="token operator">-</span> payment<span class="token punctuation">.</span>PlatformFee<span class="token punctuation">,</span></span>
<span class="line">            <span class="token string">"verified"</span><span class="token punctuation">:</span>       <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    p<span class="token punctuation">.</span><span class="token function">publishEvent</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> event<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
