<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="二、数据质量保障" tabindex="-1"><a class="header-anchor" href="#二、数据质量保障"><span>二、数据质量保障</span></a></h3>
<h4 id="_2-1-数据一致性检查" tabindex="-1"><a class="header-anchor" href="#_2-1-数据一致性检查"><span>2.1 数据一致性检查</span></a></h4>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token keyword">type</span> ConsistencyChecker <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    clientDataWindow time<span class="token punctuation">.</span>Duration</span>
<span class="line">    serverDataWindow time<span class="token punctuation">.</span>Duration</span>
<span class="line">    tolerance        <span class="token builtin">float64</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>c <span class="token operator">*</span>ConsistencyChecker<span class="token punctuation">)</span> <span class="token function">CheckDailyConsistency</span><span class="token punctuation">(</span>date time<span class="token punctuation">.</span>Time<span class="token punctuation">)</span> ConsistencyReport <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 获取客户端和服务器的DAU数据</span></span>
<span class="line">    clientDAU <span class="token operator">:=</span> c<span class="token punctuation">.</span><span class="token function">getClientDAU</span><span class="token punctuation">(</span>date<span class="token punctuation">)</span></span>
<span class="line">    serverDAU <span class="token operator">:=</span> c<span class="token punctuation">.</span><span class="token function">getServerDAU</span><span class="token punctuation">(</span>date<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 计算差异百分比</span></span>
<span class="line">    diff <span class="token operator">:=</span> math<span class="token punctuation">.</span><span class="token function">Abs</span><span class="token punctuation">(</span><span class="token function">float64</span><span class="token punctuation">(</span>clientDAU<span class="token operator">-</span>serverDAU<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">/</span> <span class="token function">float64</span><span class="token punctuation">(</span>serverDAU<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    report <span class="token operator">:=</span> ConsistencyReport<span class="token punctuation">{</span></span>
<span class="line">        Date<span class="token punctuation">:</span>      date<span class="token punctuation">,</span></span>
<span class="line">        ClientDAU<span class="token punctuation">:</span> clientDAU<span class="token punctuation">,</span></span>
<span class="line">        ServerDAU<span class="token punctuation">:</span> serverDAU<span class="token punctuation">,</span></span>
<span class="line">        Difference<span class="token punctuation">:</span> diff<span class="token punctuation">,</span></span>
<span class="line">        Status<span class="token punctuation">:</span>    <span class="token string">"normal"</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> diff <span class="token operator">></span> c<span class="token punctuation">.</span>tolerance <span class="token punctuation">{</span></span>
<span class="line">        report<span class="token punctuation">.</span>Status <span class="token operator">=</span> <span class="token string">"anomaly"</span></span>
<span class="line">        report<span class="token punctuation">.</span>Alert <span class="token operator">=</span> <span class="token boolean">true</span></span>
<span class="line">        report<span class="token punctuation">.</span>Reason <span class="token operator">=</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">"DAU差异过大: %.2f%%"</span><span class="token punctuation">,</span> diff<span class="token operator">*</span><span class="token number">100</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> report</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-2-异常检测" tabindex="-1"><a class="header-anchor" href="#_2-2-异常检测"><span>2.2 异常检测</span></a></h4>
<div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre v-pre><code class="language-go"><span class="line"><span class="token keyword">type</span> AnomalyDetector <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    models <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token operator">*</span>TimeSeriesModel</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>a <span class="token operator">*</span>AnomalyDetector<span class="token punctuation">)</span> <span class="token function">DetectAnomaly</span><span class="token punctuation">(</span>metric <span class="token builtin">string</span><span class="token punctuation">,</span> value <span class="token builtin">float64</span><span class="token punctuation">,</span> timestamp time<span class="token punctuation">.</span>Time<span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">    model<span class="token punctuation">,</span> exists <span class="token operator">:=</span> a<span class="token punctuation">.</span>models<span class="token punctuation">[</span>metric<span class="token punctuation">]</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token operator">!</span>exists <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span> <span class="token comment">// 无基线数据</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 预测期望值</span></span>
<span class="line">    expected <span class="token operator">:=</span> model<span class="token punctuation">.</span><span class="token function">Predict</span><span class="token punctuation">(</span>timestamp<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 计算标准差</span></span>
<span class="line">    stdDev <span class="token operator">:=</span> model<span class="token punctuation">.</span><span class="token function">GetStandardDeviation</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3-sigma规则检测异常</span></span>
<span class="line">    <span class="token keyword">return</span> math<span class="token punctuation">.</span><span class="token function">Abs</span><span class="token punctuation">(</span>value<span class="token operator">-</span>expected<span class="token punctuation">)</span> <span class="token operator">></span> <span class="token number">3</span><span class="token operator">*</span>stdDev</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr>
